  "Заполнить subject_definitions и retention_analysis по карточкам «Персонажей» этого промпта (их метки, имена, внешность, что сохранить, голос). Ctrl+Z — отменить": "Fill subject_definitions and retention_analysis from this prompt's “Characters” cards (their labels, names, appearance, what to retain, voice). Ctrl+Z — undo",
