  "<span class=\"warn\" title=\"Метки этих карточек в промпте не упомянуты — при генерации добавится строка по типу карточки (например «&lt;Picture N&gt; shows Anna…»). «◈ Набросать из персонажей» опишет их явно.\">◈ не упомянуты: {0}</span>": "<span class=\"warn\" title=\"These cards' labels are not mentioned in the prompt — generation adds a line by card type (e.g. “&lt;Picture N&gt; shows Anna…”). “◈ Draft from characters” describes them explicitly.\">◈ not mentioned: {0}</span>",
  "<span class=\"bad\" title=\"Персонажей с такими номерами у этого промпта нет (всего {0})\">✕ {1}</span>": "<span class=\"bad\" title=\"This prompt has no characters with these numbers (total {0})\">✕ {1}</span>",
