  "<span class=\"warn\" title=\"Карточка выключена — в генерацию не подаётся, хотя промпт её называет\">◈ выключены: {0}</span>": "<span class=\"warn\" title=\"The card is off — not fed to generation, although the prompt names it\">◈ off: {0}</span>",
  "<span class=\"warn\" title=\"Участок не подаёт голоса карточек\">◈ голос в участке не идёт: {0}</span>": "<span class=\"warn\" title=\"Spans don't feed card voices\">◈ voice not used in span: {0}</span>",
