  "\nЧерновик: маленький размер, быстро — для подбора промптов и дублей": "\nDraft: small size, fast — for trying prompts and takes",
  "\nФинал из черновика: каждый черновик увеличивается и дорабатывается (звук черновика сохраняется 1:1)": "\nFinal from draft: each draft is upscaled and refined (the draft's sound is kept 1:1)",
