  "Сменить категорию": "Change category",
  "{0}\nКлик — добавить в выбранный отрезок / убрать. Можно перетащить на отрезок.": "{0}\nClick — add to / remove from the selected segment. Can be dragged onto a segment.",
  "Ассеты ": "Assets ",
  "<span>Загрузить</span>": "<span>Upload</span>",
  "В этой категории пусто": "This category is empty",
  "Загрузите референсы персонажей, локаций и предметов. В промптах отрезков они станут <Picture N>.": "Upload references of characters, locations and objects. In segment prompts they become <Picture N>.",
