  "Участок: выделить и пересоздать часть ролика": "Span: select and regenerate part of the video",
  "ПКМ по отрезку": "Right-click a segment",
  "меню: новый дубль, разрезать, маркер…": "menu: new take, split, marker…",
  "свернуть редактор": "collapse the editor",
  "вставить картинку в ассеты": "paste an image into assets",
  "Горячие клавиши": "Hotkeys",
  "Как это работает": "How it works",
  "Каждый отрезок — отдельная генерация H3 длиной <b>17k+5</b> кадров (24 fps). Отрезок в режиме <b>«Продление»</b> начинается с хвоста предыдущего: кадры перекрытия фиксируются в латенте и подаются как ключевой клип, а последний кадр предыдущего отрезка добавляется ещё одним <b>&lt;Picture N&gt;</b>. Так персонажи и свет не «плывут» между отрезками.": "Each segment is a separate H3 generation of <b>17k+5</b> frames (24 fps). A segment in <b>“Continuation”</b> mode starts from the tail of the previous one: the overlap frames are locked in the latent and fed as a key clip, and the previous segment's last frame is added as one more <b>&lt;Picture N&gt;</b>. This keeps characters and lighting from drifting between segments.",
  "<b>«Новая сцена»</b> — монтажная склейка: отрезок генерируется с нуля, без связи с предыдущим.": "<b>“New scene”</b> is a hard cut: the segment is generated from scratch, unlinked from the previous one.",
  "Готовые отрезки кэшируются в <b>output/h3labstudio/": "Finished segments are cached in <b>output/h3labstudio/",
  "</b>. Повторный запуск пропускает неизменённые отрезки; изменение отрезка пересчитывает его и все продолжения после него.": "</b>. A re-run skips unchanged segments; changing a segment recomputes it and every continuation after it.",
  "Обучающий диапазон H3 — {0}–{1} кадров ({2}–{3} с) на отрезок. Сейчас в проекте: {4} кадров, {5} с.": "H3 training range: {0}–{1} frames ({2}–{3} s) per segment. Project now: {4} frames, {5} s.",
  "<span>Очистить кэш проекта</span>": "<span>Clear project cache</span>",
  "Готовые дубли остаются (восстановятся без генерации)": "Finished takes stay (restored without generation)",
  "Кэш и все готовые дубли (кроме зафиксированных)": "Cache and all finished takes (except locked ones)",
  "…и дубли": "…and takes",
  "Загрузка видео: {0}… (большие файлы — до минуты)": "Uploading video: {0}… (large files — up to a minute)",
