  "Добавьте первый отрезок — кнопкой ниже или «+ Отрезок» на таймлайне.": "Add the first segment — with the button below or “+ Segment” on the timeline.",
  "<span>Добавить отрезок</span>": "<span>Add segment</span>",
  "Шов {0}→{1}: {2} (скачок ×{3} к обычному движению кадра; < 1.2 — незаметен, < 1.8 — лёгкий)": "Seam {0}→{1}: {2} (jump ×{3} vs normal frame motion; < 1.2 — invisible, < 1.8 — slight)",
  "\nВыравнивание яркости и цвета: до ×{0} ({1}) → после ×{2}": "\nBrightness and color matching: before ×{0} ({1}) → after ×{2}",
