  " — он больше не продолжает предыдущий (новая сцена)": " — it no longer continues the previous one (new scene)",
  " · Ctrl+Z — вернуть": " · Ctrl+Z — undo",
  "Промежуток перед отрезком {0} убран": "Gap before segment {0} removed",
  "<b>∩</b><span>Магнит</span>": "<b>∩</b><span>Magnet</span>",
  "Магнит включён: клипы прилипают друг к другу, перетаскивание клипа меняет порядок.\nAlt (или Ctrl) при перетаскивании — свободно, с промежутком. Клик — выключить": "Magnet on: clips stick to each other, dragging a clip reorders.\nAlt (or Ctrl) while dragging — free, with a gap. Click — turn off",
  "Магнит выключен: перетаскивание клипа сдвигает его (и всё после него) и оставляет промежуток;\nближе 10 px к предыдущему клипу — прилипает. Бросьте на предыдущий клип — порядок поменяется.\nAlt (или Ctrl) при перетаскивании — магнит. Клик — включить": "Magnet off: dragging a clip moves it (and everything after it) and leaves a gap;\nwithin 10 px of the previous clip — it snaps. Drop onto the previous clip — the order changes.\nAlt (or Ctrl) while dragging — magnet. Click — turn on",
  "∩ Магнит включён: клипы прилипают, перетаскивание меняет порядок": "∩ Magnet on: clips stick together, dragging reorders",
  "∩ Магнит выключен: перетаскивание оставляет промежуток": "∩ Magnet off: dragging leaves a gap",
  "Идёт генерация — клипы двигаются после неё": "Generation is running — clips can move after it",
  "↔ поставить на место {0}": "↔ move to position {0}",
  " · Alt — магнит": " · Alt — magnet",
  "вплотную к предыдущему": "flush with the previous one",
  "Отрезок перемещён на позицию {0} · Ctrl+Z — вернуть": "Segment moved to position {0} · Ctrl+Z — undo",
  "Отрезок {0} вплотную к предыдущему": "Segment {0} is flush with the previous one",
  " — снова продолжение": " — a continuation again",
  "Промежуток {0} кадр. ({1} с): чёрный кадр и тишина.\n«Заполнить» — мост/пролог поверх него · клик — выбрать (Del — убрать) · правый клик — меню.\nПеретаскивание клипа (магнит выключен) — изменить": "Gap of {0} fr. ({1} s): black frame and silence.\n“Fill” — bridge/prologue over it · click — select (Del — remove) · right-click — menu.\nDrag the clip (magnet off) — change it",
  "⟷ {0} с": "⟷ {0} s",
  "Заполнить промежуток генерацией: мост {0} → {1} (конец сцены до и начало следующей — контекст)": "Fill the gap by generation: bridge {0} → {1} (end of the scene before and start of the next are context)",
  "Заполнить промежуток генерацией: пролог перед отрезком 1 (контекст — начало отрезка)": "Fill the gap by generation: prologue before segment 1 (context — the segment's start)",
