  "★ Персонаж": "★ Character",
  "Усилить сходство персонажа в отрезке под маркером. У H3 нет параметра силы референса, поэтому усиление делается акцентом в промпте": "Boost a character's likeness in the segment under the marker. H3 has no reference strength parameter, so the boost is an emphasis in the prompt",
