  "✕ Удалить проект «{0}»?": "✕ Delete project “{0}”?",
  "Проект исчезнет из списка. Отменить это нельзя.": "The project disappears from the list. This can't be undone.",
  "Файлы проекта собраны в его папку: {0}": "Project files gathered into its folder: {0}",
  " · не найдено: {0}": " · not found: {0}",
  "по умолчанию: папка проекта / export": "default: project folder / export",
  "С кэшем латентов (большой архив: продолжение и апскейл без перегенерации)": "With the latent cache (large archive: continuation and upscale without regenerating)",
  "В архив попадут проект, все его ассеты (картинки, аудио, видео) и папка генераций: дубли, финалы, зафиксированные отрезки.": "The archive includes the project, all its assets (images, audio, video) and the generations folder: takes, finals, locked segments.",
  "Экспорт": "Export",
  "Экспорт MP4": "MP4 export",
  "только итоговый файл — кэш и дубли не меняются": "the final file only — cache and takes stay untouched",
  "Плёночное зерно (0 = выкл)": "Film grain (0 = off)",
  "Промпт второго прохода (пусто = промпт отрезка)": "Second-pass prompt (empty = the segment prompt)",
  "Маска замены персонажа": "Character-swap mask",
  "только для отрезков с заменой": "for swap segments only",
  "Расширение маски, px": "Mask growth, px",
  "Мягкий край, px": "Soft edge, px",
  "Объединение по кадрам": "Frame union",
  "Заливать дырки внутри силуэта": "Fill holes inside the silhouette",
  "Очки, промежутки между руками: без заливки они попадут в замену.": "Glasses, gaps between the arms: without the fill they end up in the replacement.",
  "Расширение добавляет исходный контур к маске, мягкий край прячет стык вклейки, объединение по кадрам ловит быстрое движение. Значения по умолчанию — из проверенного воркфлоу.": "The growth keeps the original outline, the soft edge hides the paste seam, the frame union catches fast motion. The defaults come from a proven workflow.",  "Enhance this video with sharp, crisp details while preserving a natural photorealistic appearance.": "Enhance this video with sharp, crisp details while preserving a natural photorealistic appearance.",
  "Второй проход может добивать детали, а не переописывать сцену: с пустым полем он получает промпт отрезка, с текстом — только этот текст (референсы те же).": "The second pass can sharpen detail instead of re-describing the scene: empty gives it the segment prompt, text gives it only that text (the references stay the same).",
  "Пресет кодировщика": "Encoder preset",
  "по умолчанию · medium": "default · medium",
  "Зерно маскирует блочность H3 на 24 fps: 0.005 — хороший старт, 0.01 — заметно. Пресеты slow/veryslow дают лучшее сжатие за большее время; на NVENC пресет не влияет.": "Grain masks H3 banding at 24 fps: 0.005 is a good start, 0.01 is visible. slow/veryslow presets compress better but take longer; the preset does not affect NVENC.",
  "Собираю архив…": "Building the archive…",
  "✓ {0} · {1} МБ · файлов {2} ": "✓ {0} · {1} MB · files {2} ",
  "Скачать": "Download",
  "Экспортировано: ": "Exported: ",
  "⇩ Экспорт «{0}» в zip": "⇩ Export “{0}” to zip",
  "Импорт «{0}»…": "Importing “{0}”…",
  "Импортирован и открыт проект «{0}»": "Project “{0}” imported and opened",
  "Не удалось импортировать: ": "Could not import: ",
  "Кто есть кто": "Who is who",
  "Каждая метка с новой строки: <Picture N>, <Video N>, <Audio N> (или своя <Subject N>) — что это (персонаж, предмет, локация, стиль, движение, голос) и что именно берётся из референса: внешность, одежда, детали, роль в ролике.": "Each label on a new line: <Picture N>, <Video N>, <Audio N> (or your own <Subject N>) — what it is (character, object, location, style, motion, voice) and what exactly is taken from the reference: look, clothing, details, role in the video.",
  "Кратко": "Summary",
  "Один абзац. Начинается с типа задачи в квадратных скобках: [reference generation], [keyframe completion], [video editing], [video continuation], [audio reuse], [audio reference] (можно сочетать через +). Что за ролик, главные герои, как используются референсы.": "One paragraph. Starts with the task type in square brackets: [reference generation], [keyframe completion], [video editing], [video continuation], [audio reuse], [audio reference] (can be combined with +). What the video is, the main characters, how the references are used.",
  "Для каждой метки — насколько точно её сохранить: fully_preserved (почти без изменений), partially_preserved (часть черт меняется), attribute_transfer (черты переносятся на другой объект), weak_reference (только стиль/атмосфера). Для аудио: fully_copy, partially_copy, reference, weak_reference.": "For each label — how exactly to preserve it: fully_preserved (almost unchanged), partially_preserved (some traits change), attribute_transfer (traits move to another object), weak_reference (style/mood only). For audio: fully_copy, partially_copy, reference, weak_reference.",
  "Основное описание": "Main description",
  "Главная часть промпта. 1–2 предложения про стиль, реализм, свет, палитру и атмосферу, затем кадры по порядку: [Shot 1], [Shot 2] At 00:03.500 … В каждом: композиция, персонаж (по референсам), действие, камера (ракурс, объектив, движение), свет, звук. Реплики: <Subject 1> (S1) says: <d>[Russian] текст</d>. Обычно 350–500 слов.": "The main part of the prompt. 1–2 sentences about style, realism, light, palette and mood, then the shots in order: [Shot 1], [Shot 2] At 00:03.500 … Each with: composition, character (per references), action, camera (angle, lens, movement), light, sound. Lines: <Subject 1> (S1) says: <d>[English] text</d>. Usually 350–500 words.",
  "Звуковая среда": "Soundscape",
  "Фон и физические звуки сцены: эмбиент, шаги, ветер, ткань, предметы. Без диалогов.": "Background and physical sounds of the scene: ambience, footsteps, wind, cloth, objects. No dialogue.",
  "Закадровая музыка": "Non-diegetic music",
