  "Структура промпта H3": "H3 prompt structure",
  "Рекомендуемый формат (Full-Reference): разделы по порядку, ключ с двоеточием в начале строки, текст — по-английски.": "Recommended format (Full-Reference): sections in order, key with a colon at the start of a line, text in English.",
