  "⚠ Разделы не по порядку — H3 обучен на порядке сверху вниз. ": "⚠ Sections out of order — H3 is trained on the top-to-bottom order. ",
  "⚠ Повтор: {0}": "⚠ Repeated: {0}",
  "Метки": "Labels",
  "<Picture N>, <Video N>, <Audio N> — номера идут в порядке референсов (картинки: персонажи → локации → другое). <Subject N> — своя метка персонажа/объекта: опишите её в subject_definitions. Наберите @, чтобы выбрать референс из списка.": "<Picture N>, <Video N>, <Audio N> — numbers follow the reference order (images: characters → locations → other). <Subject N> — your own character/object label: describe it in subject_definitions. Type @ to pick a reference from the list.",
  "Шаблон вставлен, прежний текст перенесён в detailed_description (Ctrl+Z — отменить)": "Template inserted, the previous text moved to detailed_description (Ctrl+Z — undo)",
  "Все метки уже есть в subject_definitions": "All labels are already in subject_definitions",
