  "Не сохранять": "Don't save",
  "Вернуться (Esc)": "Go back (Esc)",
  "Участок: тяните по видеодорожке — внутри сцены, через склейку / промежуток (мост), в промежутке до сцены (пролог) или за её конец · Esc — выход": "Span: drag along the video track — inside a scene, across a cut / gap (bridge), in the gap before a scene (prologue) or past its end · Esc — exit",
  "<b>✂</b><span>Участок</span>": "<b>✂</b><span>Span</span>",
  "Пересоздать участок (R): включите и тяните по таймлайну — выделенная часть ролика перегенерируется,\nа видео и звук до и после неё остаются и служат контекстом.\nВыделение может пересекать склейку или промежуток (мост), начинаться в промежутке до сцены (пролог)\nили заходить за её конец (продолжение). Повторное нажатие или Esc — выход": "Regenerate span (R): turn on and drag along the timeline — the selected part of the video is regenerated,\nwhile the video and sound before and after it stay and serve as context.\nThe selection can cross a cut or a gap (bridge), start in the gap before a scene (prologue)\nor run past its end (continuation). Press again or Esc — exit",
  "тяните по видеодорожке — можно через склейку или промежуток · Esc — выход": "drag along the video track — across a cut or gap is fine · Esc — exit",
  "Выделите участок на отрезках таймлайна": "Select a span on the timeline segments",
  "Не больше {0} участков": "No more than {0} spans",
  "Участок: ": "Span: ",
  "Участок {0}–{1} с (сетка H3: 17 кадров) · допишите промпт и нажмите «↻ Пересоздать»": "Span {0}–{1} s (H3 grid: 17 frames) · write a prompt and click “↻ Regenerate”",
  "Удалено участков: {0} (их клип убран)": "Spans deleted: {0} (their clip was removed)",
  "Участок удалён · Ctrl+Z — вернуть": "Span deleted · Ctrl+Z — undo",
  "Контекст до: {0} кадр. — остаётся как есть и задаёт начало": "Context before: {0} fr. — kept as is and sets the start",
  "Контекст после: {0} кадр. — остаётся как есть и задаёт конец": "Context after: {0} fr. — kept as is and sets the end",
  " · {0} с": " · {0} s",
  " · дубль {0}": " · take {0}",
  " · оригинал": " · original",
  " · ↑{0}Мп": " · ↑{0}MP",
  "Участок {0}: пересоздаётся {1}–{2} ({3} кадр.)\nКонтекст: {4} кадр. до · {5} кадр. после · окно H3 {6} кадр.": "Span {0}: regenerating {1}–{2} ({3} fr.)\nContext: {4} fr. before · {5} fr. after · H3 window {6} fr.",
