  "Дубль устарел: изменились клипы или настройки под участком — в ролике сейчас пусто/старое. ↻ Пересоздать — в карточке участка или в меню (правый клик)": "Take outdated: the clips or settings under the span changed — the video shows empty/old frames now. ↻ Regenerate — in the span card or the menu (right-click)",
