  "Применены глобальные настройки ({0} парам.) — {1} клип(ов) устарели. «Только этот проект» в «Настройках» — оставить проекту свои": "Global settings applied ({0} params) — {1} clip(s) outdated. “This project only” in “Settings” keeps the project's own",
