  "✎ Черновик только этого клипа: {0}×{1}, {2} («Настройки» → «Этап 1»)": "✎ Draft of this clip only: {0}×{1}, {2} (“Settings” → “Stage 1”)",
  "✦ Чистовик только этого клипа: черновик (если нет) → апскейл → доработка σ {0} до {1}×{2}, {3} («Настройки» → «Этап 2»)": "✦ Final of this clip only: draft (if missing) → upscale → refine σ {0} to {1}×{2}, {3} (“Settings” → “Stage 2”)",
  "✦ Чистовик только этого клипа: сразу {0}×{1}, {2} («Настройки» → «Генерация: 1 этап»)": "✦ Final of this clip only: straight {0}×{1}, {2} (“Settings” → “Generation: 1 stage”)",
  "✎ Черновик": "✎ Draft",
  "✦ Чистовик": "✦ Final",
  "Отрезок {0}: сначала сгенерируйте клип (результат должен быть актуальным)": "Segment {0}: generate the segment first (the result must be up to date)",
