  "Пропускать неизменённые отрезки": "Skip unchanged segments",
  "Общие файлы старых версий (input/h3labstudio, _thumbs), на которые не ссылается ни один сохранённый проект": "Shared files from older versions (input/h3labstudio, _thumbs) that no saved project refers to",
  "Очистить неиспользуемое": "Clean up unused",
