  "[H3ZS] в консоли ComfyUI: запуск, отрезки, шаги, стыки и звук": "[H3ZS] in the ComfyUI console: run, segments, steps, joints and sound",
  "Пресеты моделей и стек LoRA — во вкладке ": "Model presets and the LoRA stack — in the ",
  "«Модели»": "“Models”",
