  "нет — превью latent2rgb": "none — latent2rgb preview",
  "Папки — стандартные ComfyUI (и extra_model_paths.yaml). После установки модели перезапустите ComfyUI.": "Folders are standard ComfyUI ones (and extra_model_paths.yaml). Restart ComfyUI after installing a model.",
  "Запас VRAM во время генерации, ГБ": "VRAM reserve during generation, GB",
  "Столько видеопамяти ComfyUI оставляет свободной, пока идёт генерация (штатный резерв --reserve-vram, поднимается только на время запуска и никогда не уменьшается). Помогает, когда открыт браузер / запись: иначе Windows выгружает VRAM в RAM и шаги идут в разы медленнее. 1 ГБ — голый рабочий стол, 2–3 ГБ — с браузером. 0 — выключено.": "How much VRAM ComfyUI keeps free while generating (the built-in --reserve-vram reserve, raised only for the run and never lowered). Helps when a browser / recording is open: otherwise Windows spills VRAM into RAM and steps get many times slower. 1 GB — bare desktop, 2–3 GB — with a browser. 0 — off.",
  "Генерация": "Generation",
  "Продление и звук": "Continuation and sound",
