  "Отрезок зафиксирован — разморозьте, чтобы перегенерировать": "The segment is locked — unlock it to regenerate",
  "Отрезок за маркером конца ролика («Длина: Фикс») — не генерируется. Сдвиньте маркер или нажмите «Маркер → конец»": "The segment is past the video end marker (“Length: Fixed”) — not generated. Move the marker or click “Marker → end”",
  "Продление: сначала сгенерируйте отрезок {0} или выберите его дубль — нужен его хвост. Или переключите этот отрезок на «Новая сцена»": "Continuation: generate segment {0} first or pick its take — its tail is needed. Or switch this segment to “New scene”",
