  "Зафиксирован после апскейла": "Locked after upscale",
  "Размер плитки. Больше — меньше плиток и быстрее, но больше VRAM; меньше — больше деталей на плитку, дольше. Кратно 32.": "Tile size. Larger — fewer tiles and faster, but more VRAM; smaller — more detail per tile, slower. Multiple of 32.",
