  "Апскейл отрезка": "Segment upscale",
  "Только этот клип (результат — новый дубль, звук 1:1)": "This clip only (the result is a new take, sound 1:1)",
  "<b>↑</b><span>Апскейл отрезка</span>": "<b>↑</b><span>Upscale segment</span>",
  "Метод и размер — Настройки → «Апскейл». Весь ролик — кнопка «↑ Апскейл» в шапке.": "Method and size — Settings → “Upscale”. The whole video — the “↑ Upscale” button in the header.",
  "Сначала сгенерируйте участок (↻ Пересоздать): апскейл делается из его дубля": "Generate the span first (↻ Regenerate): the upscale is made from its take",
  "Участок {0}: апскейл {1} уже есть": "Span {0}: upscale {1} already exists",
  "Участок {0}: апскейл {1} → {2} · {3} (дубль из кэша, звук 1:1)": "Span {0}: upscale {1} → {2} · {3} (take from the cache, sound 1:1)",
  "Участок {0}: апскейл убран · Ctrl+Z — вернуть": "Span {0}: upscale removed · Ctrl+Z — undo",
  "↑ Апскейл участка ({0})": "↑ Upscale span ({0})",
  "↑ Апскейл участка": "↑ Upscale span",
  "Дубль участка: {0} → {1} (метод и размер — Настройки → «Апскейл»)": "Span take: {0} → {1} (method and size — Settings → “Upscale”)",
  "Апскейл участка": "Span upscale",
  "Апскейл дубля участка (его окно + доработка, звук 1:1); правый клик по участку — другой метод / размер": "Upscale the span's take (its window + refine, sound 1:1); right-click the span — another method / size",
  "<b>↑</b><span>Апскейл</span>": "<b>↑</b><span>Upscale</span>",
  "↑ Апскейл всего ролика: {0} отр. · {1} → {2} ({3})\nКаждый отрезок увеличивается своим окном и дорабатывается коротким проходом H3, звук 1:1; готовые берутся из кэша.\nПравый клик — другой метод или размер": "↑ Upscale the whole video: {0} seg. · {1} → {2} ({3})\nEach segment is upscaled in its own window and refined with a short H3 pass, sound 1:1; finished ones come from the cache.\nRight-click — another method or size",
  "↑ Апскейл всего ролика": "↑ Upscale the whole video",
  "Обученный латентный апскейлер H3 (быстро, без декода/энкода) → доработка": "H3's trained latent upscaler (fast, no decode/encode) → refine",
  "Апскейл → синхронные плитки (SyncTile): каждая плитка видит промпт и референсы отрезка": "Upscale → synchronized tiles (SyncTile): each tile sees the segment's prompt and references",
  " · вход: {0} · у метода свои настройки": " · input: {0} · the method has its own settings",
  "Размер кадра после апскейла в мегапикселях. Пропорции — как у проекта, стороны кратны 32": "Frame size after upscale in megapixels. Aspect as in the project, sides are multiples of 32",
  " (не больше кадра)": " (not larger than the frame)",
  "свой · {0} Мп → {1}×{2}": "custom · {0} MP → {1}×{2}",
  "свой размер, Мп…": "custom size, MP…",
  "Кадр проекта {0}×{1} ({2} Мп) → ": "Project frame {0}×{1} ({2} MP) → ",
  " ({0} Мп, ×{1})": " ({0} MP, ×{1})",
  "Длинный клип увеличивается по кускам: каждый кусок — свой апскейл и доработка, затем VRAM освобождается. Меньше кусок — меньше VRAM, но больше перекрытий (дольше). Длина прилипает к сетке H3 (17k+5 кадров)": "A long clip is upscaled in chunks: each chunk gets its own upscale and refine, then VRAM is freed. Smaller chunk — less VRAM, but more overlaps (slower). The length snaps to the H3 grid (17k+5 frames)",
  "≈{0} с → {1} кадр. ({2} с)": "≈{0} s → {1} fr. ({2} s)",
  " · по умолчанию": " · default",
  "Перекрытие соседних кусков: следующий кусок продолжает чистый хвост предыдущего (как продление), стык смешивается при декодировании": "Overlap of neighboring chunks: the next chunk continues the clean tail of the previous one (like a continuation), the joint is blended on decode",
  "{0} с → {1}": "{0} s → {1}",
  "По кускам ({0})": "In chunks ({0})",
  "Кусков на клип: {0}.": "Chunks per clip: {0}.",
  " Плитки работают внутри каждого куска.": " Tiles work inside each chunk.",
  "Клип целиком за один проход — нужно больше VRAM.": "The whole clip in one pass — needs more VRAM.",
  "Сила доработки (σ старта): меньше — бережнее, больше — больше новых деталей": "Refine strength (start σ): lower — gentler, higher — more new detail",
  "Шаги доработки после апскейла (для этого метода)": "Refine steps after upscale (for this method)",
  "{0} шаг.": "{0} steps",
  "как «Этап 2» · {0} шаг.": "as “Stage 2” · {0} steps",
  "как «Этап 2» · {0}": "as “Stage 2” · {0}",
  "Метод": "Method",
  "Ниже — настройки метода «{0}». У каждого метода свои: переключение их не сбрасывает.": "Below are the settings of the “{0}” method. Each method has its own: switching doesn't reset them.",
  "Куски по времени": "Time chunks",
  "Сила доработки": "Refine strength",
  "Шаги доработки": "Refine steps",
  "Сэмплер": "Sampler",
  "Расписание": "Scheduler",
  "Плитки": "Tiles",
  "«↑ Апскейл» в шапке — весь ролик (каждый отрезок своим окном, длинные — по кускам, звук 1:1, готовые из кэша). ↑ на клипе или в его меню — только этот клип. Результат — новый дубль, старый можно вернуть.": "“↑ Upscale” in the header — the whole video (each segment in its own window, long ones in chunks, sound 1:1, finished ones from the cache). ↑ on a segment or in its menu — this segment only. The result is a new take; the old one can be restored.",
  "Видео загружено: {0} · перетащите на дорожку (футаж) или на отрезок (референс <Video>)": "Video loaded: {0} · drag onto the track (footage) or onto a segment (reference <Video>)",
  "{0} · зафикс.": "{0} · locked",
  "Убрать из проекта (файл остаётся)": "Remove from project (the file stays)",
