  "{0}\n{1}{2}{3}\nПеретащите на пустую часть видеодорожки — футаж (продолжить / перегенерировать часть).\nНа отрезок или клик — референс <Video> выбранного отрезка.": "{0}\n{1}{2}{3}\nDrag onto an empty part of the video track — footage (continue / regenerate a part).\nOnto a segment or click — a <Video> reference of the selected segment.",
  "⊠ Фикс": "⊠ Lock",
  "Этот файл лежит на таймлайне как футаж. Убрать ассет и превратить эти клипы в обычные отрезки?": "This file is on the timeline as footage. Remove the asset and turn these clips into regular segments?",
