  "Промпт и референсы ниже применяются. Чтобы перегенерировать только часть файла — разрежьте футаж (S) и включите «Перегенерировать» у нужного куска.": "The prompt and references below apply. To regenerate only part of the file, split the footage (S) and turn on “Regenerate” for the piece you need.",
