  "Базовый шаблон задаёт роль ассистента и структуру промпта MiniMax H3. Сохраните свой вариант пресетом — переключение в один клик.": "The base template sets the assistant's role and the MiniMax H3 prompt structure. Save your own version as a preset — one-click switching.",
