  "Сервер запущен без ассистента (старая версия H3ZeroStudio). Перезапустите ComfyUI — тогда заработают выбор модели, файлы и API. Введённые настройки сохраняются в проекте и не потеряются.": "The server runs without the assistant (an old H3ZeroStudio version). Restart ComfyUI — then model picking, files and the API will work. The settings you enter are saved into the project and will not be lost.",
