  "Kitchen attention (Comfy Kitchen)": "Kitchen attention (Comfy Kitchen)",
  "Встроено в ComfyUI (comfy_kitchen INT8). По умолчанию, если ядро есть на этой GPU. Тот же бэкенд, что нода «Model Attention Backend» / флаг --use-ck-attention.": "Built into ComfyUI (comfy_kitchen INT8). On by default when the kernel is available on this GPU. Same backend as the “Model Attention Backend” node / --use-ck-attention flag.",
  "Пакет sageattention. Недоступно — установите sageattention и перезапустите ComfyUI.": "The sageattention package. Unavailable — install sageattention and restart ComfyUI.",
  "Пакет flash-attn. Недоступно — установите flash-attn и перезапустите ComfyUI.": "The flash-attn package. Unavailable — install flash-attn and restart ComfyUI.",
  "Стандартный scaled_dot_product_attention PyTorch.": "Standard PyTorch scaled_dot_product_attention.",
  "авто (первый найденный)": "auto (first found)",
  "Предиктор Veda": "Veda predictor",
  "Предиктор из models/veda/. Вызов veda_comfy.comfy_patch.apply — без проводов.": "Predictor from models/veda/. Calls veda_comfy.comfy_patch.apply — no wiring.",
  "Нет предиктора: положите .safetensors в models/veda/.": "No predictor: put a .safetensors file in models/veda/.",
  "Установите custom node Veda Sparse Attention (veda-sparse/Veda-on-ComfyUI) и перезапустите ComfyUI.": "Install the Veda Sparse Attention custom node (veda-sparse/Veda-on-ComfyUI) and restart ComfyUI.",
  "TeaCache (кэш шагов H3)": "TeaCache (H3 step cache)",
  "Таймстеп-кэш H3 (Icyoung/ComfyUI-MiniMaxH3-TeaCache или совместимый). Может чуть снизить детализацию.": "H3 timestep cache (Icyoung/ComfyUI-MiniMaxH3-TeaCache or compatible). May slightly reduce detail.",
  "Не установлено: поставьте ComfyUI-MiniMaxH3-TeaCache (или совместимый) в custom_nodes.": "Not installed: put ComfyUI-MiniMaxH3-TeaCache (or compatible) in custom_nodes.",
  "порог TeaCache": "TeaCache threshold",
  "torch.compile через comfy_api (как нода TorchCompileModel). Первый проход медленнее.": "torch.compile via comfy_api (like the TorchCompileModel node). First pass is slower.",
  "comfy_api.torch_helpers недоступен в этой сборке ComfyUI.": "comfy_api.torch_helpers is unavailable in this ComfyUI build.",
  "Патчи навешиваются на модель H3 при загрузке (без проводов), в том числе на доработку апскейла. Бэкенды внимания взаимоисключающие.": "Patches are attached to the H3 model on load (no wiring), including upscale refine. Attention backends are mutually exclusive.",
