  "Пресет / модель": "Preset / model",
  "Окна (латент + доработка)": "Windows (latent + refine)",
  "Окна: обученный латентный апскейлер H3 → доработка окнами (быстро, без декода/энкода)": "Windows: trained H3 latent upscaler → windowed refine (fast, no decode/encode)",
  "Плитки: апскейл → синхронные плитки (SyncTile): каждая плитка видит промпт и референсы отрезка": "Tiles: upscale → SyncTile: each tile sees the clip prompt and refs",
  "растяжение латента": "latent stretch",
  "растяжение латента (нет модели апскейлера)": "latent stretch (no upscaler model)",
  "Нет обученного латентного апскейлера H3 — латент просто растянут (trilinear), качество ниже. Нужна модель в models/latent_upscale_models и одна из нод: встроенная MiniMaxH3LatentUpscaleWithModel (ComfyUI ≥ PR #17412), PixaromaH3LatentUpscale (Pixaroma ≥ 1.4.238) или MinimaxH3LatentUpscaler3D (LBH).": "No trained H3 latent upscaler — latent is only stretched (trilinear), lower quality. Need a model in models/latent_upscale_models and one of: built-in MiniMaxH3LatentUpscaleWithModel (ComfyUI ≥ PR #17412), PixaromaH3LatentUpscale (Pixaroma ≥ 1.4.238), or MinimaxH3LatentUpscaler3D (LBH).",
  "Финал из черновика: выбранный дубль-черновик увеличивается до финального размера обученным латентным апскейлером и дорабатывается.": "Final from draft: the selected draft take is upscaled to final size with the trained latent upscaler and refined.",
  "Футаж «как есть»: его кадры кодируются VAE и проходят тот же апскейл + доработку (σ {0}) — мелкие детали восстанавливаются.": "Footage “as is”: its frames are VAE-encoded and go through the same upscale + refine (σ {0}) — fine detail is restored.",
  "Прогресс восстановлен после перезагрузки": "Progress restored after reload",
  " · из галереи (последний итог; текущий ролик помечен устаревшим)": " · from gallery (last result; current reel marked stale)",
  " · прошлый итог проекта (таймлайн изменился)": " · previous project result (timeline changed)",
  "Папка на компьютере, где запущен ComfyUI (например D:\\\\Видео\\\\H3). Относительный путь — внутри ComfyUI/output.": "Folder on the machine running ComfyUI (e.g. D:\\\\Video\\\\H3). A relative path is inside ComfyUI/output.",
  "Переведи на русский кратко, без правок смысла:\n\n": "Translate into Russian briefly, without changing the meaning:\n\n",
  " · {0} Мп": " · {0} MP",
  "Время": "Time",
  "Не удалось скопировать": "Could not copy",
  "⧉ Копировать промпт": "⧉ Copy prompt",
  "Папка на компьютере, где запущен ComfyUI (например D:\\Видео\\H3). Относительный путь — внутри ComfyUI/output.": "Folder on the machine running ComfyUI (e.g. D:\\Video\\H3). A relative path is inside ComfyUI/output.",
  "установлено": "installed",
  "Нет обученного латентного апскейлера H3 — латент просто растянут (trilinear), качество ниже. Нужна модель в models/latent_upscale_models и одна из нод: встроенная MiniMaxH3LatentUpscaleWithModel (ComfyUI ≥ PR #17412), PixaromaH3LatentUpscale (Pixaroma ≥ 1.4.238) или MinimaxH3LatentUpscaler3D (LBH).": "No trained H3 latent upscaler — latent is only stretched (trilinear), lower quality. Need a model in models/latent_upscale_models and one of: built-in MiniMaxH3LatentUpscaleWithModel (ComfyUI ≥ PR #17412), PixaromaH3LatentUpscale (Pixaroma ≥ 1.4.238), or MinimaxH3LatentUpscaler3D (LBH).",
  "Финал из черновика: выбранный дубль-черновик увеличивается до финального размера обученным латентным апскейлером H3 и дорабатывается коротким проходом H3 с тем же промптом и референсами. Композиция, движение и звук черновика сохраняются.": "Final from draft: the selected draft take is upscaled to final size with the trained H3 latent upscaler and refined with a short H3 pass using the same prompt and refs. Draft composition, motion and sound are kept.",
  "Папка на компьютере, где запущен ComfyUI (например D:\\Видео\\H3). Относительный путь — внутри ComfyUI/output": "Folder on the machine running ComfyUI (e.g. D:\\Video\\H3). A relative path is inside ComfyUI/output",
  "Файлы сохраняются в стандартные папки ComfyUI (folder_paths / extra_model_paths.yaml). Загрузка потоковая с докачкой (.part). Опциональные модели «Скачать все» не трогает.": "Files are saved to standard ComfyUI folders (folder_paths / extra_model_paths.yaml). Streaming download with resume (.part). “Download all” skips optional models.",
  "Футаж «как есть»: его кадры кодируются VAE и проходят тот же апскейл + доработку (σ {0}) — мелкие детали могут слегка измениться. Звук не трогается.": "Footage “as is”: its frames are VAE-encoded and go through the same upscale + refine (σ {0}) — fine detail may change slightly. Sound is left untouched.",
  "Идея сцены или вопрос — Enter отправит": "A scene idea or question — Enter to send",
