  "Эксперимент Character Swap: исходный клип задаёт движения, референс <Picture 1> — внешность. На этом проходе denoise не используется.": "Character Swap experiment: the source clip sets the motion, the <Picture 1> reference sets the look. This pass does not use denoise.",
